{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const targets = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const out: { shortId: string; owner: string }[] = [];
  for (const i of targets) {
    const blame = await sdk.github.getBlame({ file: i.filename, line: i.lineNumber });
    out.push({ shortId: i.shortId, owner: blame.authorEmail });
  }
  return { total: issues.length, count: targets.length, out };
}"}

